66: 
67:   const pinWidget = (widget: PinnedWidget) => {
68:     const current = getPinnedWidgets().filter((w) => w.id !== widget.id);
69:     const updated = [widget, ...current];
70:     savePinnedWidgets(updated);
71:     setWidgets(updated);
72:   };
73: 
74:   const unpinWidget = (id: string) => {
75:     const updated = getPinnedWidgets().filter((w) => w.id !== id);
76:     savePinnedWidgets(updated);
77:     setWidgets(updated);
78:   };
79: 
80:   const isPinned = (id: string) => widgets.some((w) => w.id === id);
81: 
82:   return { widgets, pinWidget, unpinWidget, isPinned };
83: }
