85: export interface DeliverableItem {
86:   id: string;
87:   artifactId: string | null;
88:   name: string;
89:   path: string;
90:   sizeBytes: number;
91:   sha256: string | null;
92:   preview: string | null;
93:   format: 'markdown' | 'pdf' | 'docx' | 'xlsx' | 'csv' | 'image' | 'html' | 'text';
94: }
95: 
96: function detectDeliverableFormat(name: string, rawFormat?: string | null): DeliverableItem['format'] {
97:   const ext = name.includes('.') ? (name.split('.').pop()?.toLowerCase() ?? '') : '';
98:   const fmt = (rawFormat ?? '').toLowerCase();
99:   if (ext === 'md' || ext === 'markdown' || fmt === 'markdown') return 'markdown';
100:   if (ext === 'pdf' || fmt === 'pdf') return 'pdf';
101:   if (ext === 'docx' || fmt === 'docx') return 'docx';
102:   if (ext === 'xlsx' || ext === 'xlsm' || fmt === 'xlsx') return 'xlsx';
103:   if (ext === 'csv' || fmt === 'csv') return 'csv';
104:   if (['png', 'jpg', 'jpeg', 'gif', 'webp', 'bmp', 'svg', 'ico'].includes(ext) || fmt === 'image' || fmt === 'screenshot') {
105:     return 'image';
106:   }
107:   if (ext === 'html' || ext === 'htm' || fmt === 'html' || fmt === 'micro_app') return 'html';
108:   return 'text';
109: }
110: 
111: function formatFileSize(bytes: number): string {
112:   if (!Number.isFinite(bytes) || bytes < 0) return '0 B';
113:   if (bytes < 1024) return `${bytes} B`;
114:   if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
115:   return `${(bytes / (1024 * 1024)).toFixed(2)} MB`;
116: }
117: 
118: interface ParsedSheet {
119:   name: string;
120:   rows: string[][];
121: }
122: 
123: function parseCsvLine(line: string, delimiter: string): string[] {
124:   const cells: string[] = [];
125:   let current = '';
126:   let inQuotes = false;
127:   for (let i = 0; i < line.length; i += 1) {
128:     const ch = line[i];
129:     if (ch === '"') {
130:       if (inQuotes && line[i + 1] === '"') {
131:         current += '"';
132:         i += 1;
133:       } else {
134:         inQuotes = !inQuotes;
135:       }
136:     } else if (ch === delimiter && !inQuotes) {
137:       cells.push(current.trim());
138:       current = '';
139:     } else {
140:       current += ch;
141:     }
142:   }
143:   cells.push(current.trim());
144:   return cells;
145: }
146: 
147: function parseSpreadsheetPreview(text: string, format: 'xlsx' | 'csv'): ParsedSheet[] {
148:   const trimmed = text.trim();
149:   if (!trimmed) return [];
150: 
151:   if (format === 'xlsx' && trimmed.includes('[sheet:')) {
152:     const blocks = trimmed.split(/(?=\[sheet:\s*[^\]]+\])/g);
153:     const sheets: ParsedSheet[] = [];
154:     for (const block of blocks) {
155:       const lines = block.trim().split(/\r?\n/);
156:       if (lines.length === 0) continue;
157:       const headerMatch = /^\[sheet:\s*([^\]]+)\]$/.exec(lines[0]?.trim() ?? '');
158:       const sheetName = headerMatch?.[1]?.trim() || 'Sheet1';
159:       const bodyLines = headerMatch ? lines.slice(1) : lines;
160:       const rows = bodyLines
161:         .filter((l) => l.trim().length > 0 && !l.startsWith('... [truncated'))
162:         .map((l) => (l.includes('\t') ? l.split('\t') : parseCsvLine(l, ',')));
163:       if (rows.length > 0) {
164:         sheets.push({ name: sheetName, rows });
165:       }
166:     }
167:     if (sheets.length > 0) return sheets;
168:   }
169: 
170:   const lines = trimmed.split(/\r?\n/).filter((l) => l.trim().length > 0);
171:   const delimiter = lines[0]?.includes('\t') ? '\t' : ',';
172:   const rows = lines.map((l) =>
173:     delimiter === '\t' ? l.split('\t') : parseCsvLine(l, ','),
174:   );
175:   return rows.length > 0 ? [{ name: 'Sheet1', rows }] : [];
176: }
