297: export function ArtifactCard({ item }: { item: DeliverableItem }) {
298:   const [expandedInline, setExpandedInline] = useState(false);
299:   const [modalOpen, setModalOpen] = useState(false);
300:   const [blobUrl, setBlobUrl] = useState<string | null>(null);
301:   const [fullText, setFullText] = useState<string | null>(item.preview);
302:   const [loadingBlob, setLoadingBlob] = useState(false);
303:   const [activeSheet, setActiveSheet] = useState(0);
304:   const [zoom, setZoom] = useState(100);
305:   const [viewMode, setViewMode] = useState<'preview' | 'code'>('preview');
306:   const [viewportWidth, setViewportWidth] = useState<'375px' | '768px' | '100%'>('100%');
307: 
308:   const { pinWidget, unpinWidget, isPinned } = usePinnedWidgets();
309:   const pinned = isPinned(item.id);
310: 
311:   const handleTogglePin = () => {
312:     if (pinned) {
313:       unpinWidget(item.id);
314:     } else {
315:       pinWidget({
316:         id: item.id,
317:         artifactId: item.artifactId,
318:         name: item.name,
319:         content: fullText ?? item.preview ?? '',
320:         format: item.format,
321:         pinnedAt: new Date().toISOString(),
322:       });
323:     }
324:   };
325: 
326:   const needsBlobForInline = item.format === 'image' || item.format === 'pdf';
327:   const needsTextFetch =
328:     !fullText &&
329:     (item.format === 'markdown' ||
330:       item.format === 'csv' ||
331:       item.format === 'text' ||
332:       item.format === 'html');
333: 
334:   useEffect(() => {
335:     let active = true;
336:     let createdUrl: string | null = null;
337: 
338:     if (item.artifactId && (needsBlobForInline || modalOpen || needsTextFetch)) {
339:       setLoadingBlob(true);
340:       api
341:         .downloadArtifactBlob(item.artifactId)
342:         .then(async (blob) => {
343:           if (!active) return;
344:           createdUrl = URL.createObjectURL(blob);
345:           setBlobUrl(createdUrl);
346:           if (
347:             !fullText &&
348:             (item.format === 'markdown' ||
349:               item.format === 'csv' ||
350:               item.format === 'text' ||
351:               item.format === 'html')
352:           ) {
353:             const text = await blob.text();
354:             if (active && text) setFullText(text);
355:           }
356:         })
357:         .catch(() => {
358:           // Fallback to preview text when stream is unreachable
359:         })
360:         .finally(() => {
361:           if (active) setLoadingBlob(false);
362:         });
363:     }
364: 
365:     return () => {
366:       active = false;
367:       if (createdUrl) URL.revokeObjectURL(createdUrl);
368:     };
369:   }, [item.artifactId, item.format, needsBlobForInline, modalOpen, needsTextFetch]);
370: 
371:   const handleDownload = async () => {
372:     try {
373:       let url = blobUrl;
374:       let revokeAfter = false;
375:       if (!url) {
376:         if (item.artifactId) {
377:           const blob = await api.downloadArtifactBlob(item.artifactId);
378:           url = URL.createObjectURL(blob);
379:           revokeAfter = true;
380:         } else if (fullText) {
381:           const blob = new Blob([fullText], { type: 'text/plain;charset=utf-8' });
382:           url = URL.createObjectURL(blob);
383:           revokeAfter = true;
384:         }
385:       }
386:       if (!url) return;
387:       const a = document.createElement('a');
388:       a.href = url;
389:       a.download = item.name;
390:       document.body.appendChild(a);
391:       a.click();
392:       document.body.removeChild(a);
393:       if (revokeAfter) setTimeout(() => URL.revokeObjectURL(url as string), 1500);
394:     } catch {
395:       // Ignore download failure
396:     }
397:   };
398: 
399:   const sheets = useMemo(() => {
400:     if (item.format !== 'xlsx' && item.format !== 'csv') return [];
401:     return parseSpreadsheetPreview(fullText ?? item.preview ?? '', item.format);
