496:           <div className="p-3.5">
497:             {item.format === 'image' ? (
498:               <div className="flex flex-col items-center justify-center overflow-hidden rounded-[8px] border border-[var(--border)] bg-[color-mix(in_srgb,var(--text)_2%,transparent)] p-2">
